class Solution {
    public boolean isAdditiveNumber(String num) {
        int n=num.length(); long limit=Integer.MAX_VALUE;
        for(int i=1;i<n;i++){ if(i>10) break;
            if(num.charAt(0)=='0' && i>1) break; long a=Long.parseLong(num.substring(0,i));
            for(int j=i+1;j<n;j++){ if(j-i>10) break;
                if(num.charAt(i)=='0' && j>i+1) break; long b=Long.parseLong(num.substring(i,j));
                if(a>limit || b>limit) break; int pos=j,count=2; long x=a,y=b;
                while(pos<n){ long z=x+y; if(z>limit) break; String t=Long.toString(z);
                    if(!num.startsWith(t,pos)) break; pos+=t.length(); x=y; y=z; count++; }
                if(pos==n && count>=3) return true;
            }
        } return false;
    }
}

class NumArray:
    def __init__(self, nums: list[int]):
        self.nums=nums[:]; self.n=len(nums); self.bit=[0]*(self.n+1)
        for i,v in enumerate(nums): self._add(i+1,v)
    def _add(self,i,delta):
        while i<=self.n: self.bit[i]+=delta; i+=i&-i
    def update(self,index: int,val: int)->None:
        delta=val-self.nums[index]; self.nums[index]=val; self._add(index+1,delta)
    def _sum(self,i):
        total=0
        while i>0: total+=self.bit[i]; i-=i&-i
        return total
    def sumRange(self,left: int,right: int)->int:
        return self._sum(right+1)-self._sum(left)

class NumArray {
    private final int[] nums, bit; private final int n;
    public NumArray(int[] values) { n=values.length; nums=values.clone(); bit=new int[n+1]; for(int i=0;i<n;i++) add(i+1,nums[i]); }
    private void add(int i,int d) { while(i<=n){bit[i]+=d;i+=i&-i;} }
    private int prefix(int i) { int s=0; while(i>0){s+=bit[i];i-=i&-i;} return s; }
    public void update(int index,int val) { int d=val-nums[index];nums[index]=val;add(index+1,d); }
    public int sumRange(int left,int right) { return prefix(right+1)-prefix(left); }
}

class Solution:
    def maxProfit(self, prices: list[int]) -> int:
        hold=float('-inf'); sold=0; rest=0
        for price in prices:
            old_hold,old_sold,old_rest=hold,sold,rest
            hold=max(old_hold,old_rest-price)
            sold=old_hold+price
            rest=max(old_rest,old_sold)
        return max(sold,rest)

class Solution {
    public int maxProfit(int[] prices) {
        int hold=Integer.MIN_VALUE/2, sold=0, rest=0;
        for(int p:prices){int h=hold,s=sold,r=rest;hold=Math.max(h,r-p);sold=h+p;rest=Math.max(r,s);}
        return Math.max(sold,rest);
    }
}

