class Solution:
    def findMinHeightTrees(self, n: int, edges: list[list[int]]) -> list[int]:
        if n<=2: return list(range(n))
        graph=[set() for _ in range(n)]
        for a,b in edges: graph[a].add(b); graph[b].add(a)
        leaves=deque(i for i in range(n) if len(graph[i])==1)
        remaining=n
        while remaining>2:
            size=len(leaves); remaining-=size
            for _ in range(size):
                leaf=leaves.popleft(); neighbor=graph[leaf].pop(); graph[neighbor].remove(leaf)
                if len(graph[neighbor])==1: leaves.append(neighbor)
        return list(leaves)

import java.util.*;
class Solution {
    public List<Integer> findMinHeightTrees(int n,int[][] edges) {
        if(n<=2){List<Integer> a=new ArrayList<>();for(int i=0;i<n;i++)a.add(i);return a;}
        List<Set<Integer>> g=new ArrayList<>();for(int i=0;i<n;i++)g.add(new HashSet<>());
        for(int[] e:edges){g.get(e[0]).add(e[1]);g.get(e[1]).add(e[0]);}
        Queue<Integer> q=new ArrayDeque<>();for(int i=0;i<n;i++)if(g.get(i).size()==1)q.offer(i);
        int remain=n;while(remain>2){int size=q.size();remain-=size;for(int z=0;z<size;z++){int leaf=q.poll();int nei=g.get(leaf).iterator().next();g.get(nei).remove(leaf);g.get(leaf).clear();if(g.get(nei).size()==1)q.offer(nei);}}
        return new ArrayList<>(q);
    }
}

class Solution:
    def maxCoins(self, nums: list[int]) -> int:
        a=[1]+nums+[1]; n=len(nums); dp=[[0]*(n+2) for _ in range(n+2)]
        for length in range(1,n+1):
            for left in range(1,n-length+2):
                right=left+length-1
                dp[left][right]=max(a[left-1]*a[k]*a[right+1]+dp[left][k-1]+dp[k+1][right] for k in range(left,right+1))
        return dp[1][n]

class Solution {
    public int maxCoins(int[] nums) {
        int n=nums.length; int[] a=new int[n+2];a[0]=a[n+1]=1;for(int i=0;i<n;i++)a[i+1]=nums[i];
        int[][] dp=new int[n+2][n+2];
        for(int len=1;len<=n;len++)for(int l=1;l+len-1<=n;l++){int r=l+len-1;for(int k=l;k<=r;k++)dp[l][r]=Math.max(dp[l][r],a[l-1]*a[k]*a[r+1]+dp[l][k-1]+dp[k+1][r]);}
        return dp[1][n];
    }
}

class Solution:
    def nthSuperUglyNumber(self, n: int, primes: list[int]) -> int:
        dp=[1]*n; idx=[0]*len(primes); vals=primes[:] 
        for i in range(1,n):
            nxt=min(vals); dp[i]=nxt
            for j,p in enumerate(primes):
                if vals[j]==nxt:
                    idx[j]+=1; vals[j]=p*dp[idx[j]]
        return dp[-1]

class Solution {
    public int nthSuperUglyNumber(int n,int[] primes) {
        int p=primes.length;int[] dp=new int[n],idx=new int[p];long[] val=new long[p];for(int j=0;j<p;j++)val[j]=primes[j];dp[0]=1;
        for(int i=1;i<n;i++){long next=Long.MAX_VALUE;for(long x:val)next=Math.min(next,x);dp[i]=(int)next;
            for(int j=0;j<p;j++)if(val[j]==next){idx[j]++;val[j]=(long)primes[j]*dp[idx[j]];}
        }return dp[n-1];
    }
}

class Solution:
    def countSmaller(self, nums: list[int]) -> list[int]:
        pairs=list(enumerate(nums)); ans=[0]*len(nums)
        def sort(lo,hi):
            if hi-lo<=1:return pairs[lo:hi]
            mid=(lo+hi)//2; left=sort(lo,mid); right=sort(mid,hi); merged=[]; i=j=0
            while i<len(left) and j<len(right):
                if left[i][1]<=right[j][1]:
                    ans[left[i][0]]+=j; merged.append(left[i]); i+=1
                else: merged.append(right[j]); j+=1
            while i<len(left): ans[left[i][0]]+=j; merged.append(left[i]); i+=1
            merged.extend(right[j:]); pairs[lo:hi]=merged; return pairs[lo:hi]
        sort(0,len(pairs)); return ans

import java.util.*;
class Solution {
    private int[] nums,idx,tmp,ans;
    public List<Integer> countSmaller(int[] values) {
        nums=values;int n=nums.length;idx=new int[n];tmp=new int[n];ans=new int[n];for(int i=0;i<n;i++)idx[i]=i;sort(0,n);List<Integer> out=new ArrayList<>();for(int x:ans)out.add(x);return out;
    }
    private void sort(int l,int r){if(r-l<=1)return;int m=(l+r)/2;sort(l,m);sort(m,r);int i=l,j=m,k=l,passed=0;
        while(i<m&&j<r){if(nums[idx[j]]<nums[idx[i]]){tmp[k++]=idx[j++];passed++;}else{ans[idx[i]]+=passed;tmp[k++]=idx[i++];}}
        while(i<m){ans[idx[i]]+=passed;tmp[k++]=idx[i++];}while(j<r)tmp[k++]=idx[j++];for(int z=l;z<r;z++)idx[z]=tmp[z];
    }
}
